{
  "up": "Select molecule_chembl_id as compound_chembl_id, canonical_smiles, compound_key, pubmed_id_or_doi, assay_description, standard_type, standard_relation, standard_value, standard_units, activity_comment, target_chembl_id, target_name, target_organism From molecule_dictionary Join activities On molecule_dictionary.molregno = activities.molregno Join assays On activities.assay_id = assays.assay_id Join target_dictionary On assays.tid = target_dictionary.tid Join compound_structures On molecule_dictionary.molregno = compound_structures.molregno Join docs On activities.doc_id = docs.doc_id Where molecule_dictionary.chembl_id = 'CHEMBL3397' And activities.bao_endpoint = 'IC50' And activities.standard_type = 'IC50' And assays.assay_organism = 'Homo sapiens' And target_dictionary.target_type = 'SINGLE PROTEIN' And target_dictionary.tid = 3397 And activities.standard_relation = '=' And activities.standard_value IS NOT NULL And activities.standard_units = 'nM' And activities.activity_comment IS NOT NULL And activities.pubmed_id IS NOT NULL Or activities.doi IS NOT NULL Order By compound_chembl_id, canonical_smiles, compound_key, pubmed_id_or_doi, assay_description, standard_type, standard_relation, standard_value, standard_units, activity_comment, target_chembl_id, target_name, target_organism"
}
